# ============================================================
# 1. LOAD TRAINED MODELS
# ============================================================
# This app first uses `trained_models` if you created it earlier in
# the same Python session. Otherwise, it loads .joblib files from
# ./analyzer_models/.

if "trained_models" not in globals() or not isinstance(trained_models, dict) or not trained_models:
    trained_models = {}
    model_folder = BASE_DIR / "analyzer_models"
    model_files = {
        "random_forest.joblib": "Random Forest",
        "linear_svm.joblib": "Linear SVM",
        "svm.joblib": "Linear SVM",
        "logistic_regression.joblib": "Logistic Regression",
        "naive_bayes.joblib": "Naive Bayes",
        "multinomial_naive_bayes.joblib": "Naive Bayes",
    }
    if model_folder.exists():
        for filename, display_name in model_files.items():
            path = model_folder / filename
            if path.exists() and display_name not in trained_models:
                trained_models[display_name] = joblib.load(path)

if not trained_models:
    raise RuntimeError(
        "No trained models were found. Put your trained .joblib models in "
        "the 'analyzer_models' folder, or define a non-empty 'trained_models' "
        "dictionary before launching this app. Expected filenames include "
        "linear_svm.joblib, logistic_regression.joblib, random_forest.joblib, "
        "and naive_bayes.joblib."
    )


def display_model_name(name):
    """Normalize model names for the interface without changing model objects."""
    key = str(name).strip().lower().replace("_", " ").replace("-", " ")
    if "svm" in key or "support vector" in key:
        return "Linear SVM"
    if "logistic" in key:
        return "Logistic Regression"
    if "random forest" in key or "randomforest" in key:
        return "Random Forest"
    if "naive" in key or "bayes" in key:
        return "Naive Bayes"
    return str(name)


# Display name -> actual key in trained_models.
model_key_by_display = {}
for actual_name in trained_models:
    display_name = display_model_name(actual_name)
    # If aliases collide, preserve the first model and avoid a broken dropdown.
    model_key_by_display.setdefault(display_name, actual_name)

preferred_order = ["Linear SVM", "Logistic Regression", "Random Forest", "Naive Bayes"]
model_names = [name for name in preferred_order if name in model_key_by_display]
model_names += [name for name in model_key_by_display if name not in model_names]
default_model = model_names[0]
MODEL_ICONS = {
    "Linear SVM": "🎯",
    "Logistic Regression": "📈",
    "Naive Bayes": "🧮",
    "Random Forest": "🌲",
}
model_choices = [(f"{MODEL_ICONS.get(name, '🤖')} {name}", name) for name in model_names]


# ============================================================
# 2. LOAD REAL METRICS (NO FAKE PLACEHOLDER SCORES)
# ============================================================
metrics_candidates = [
    BASE_DIR / "analyzer_metrics.csv",
    BASE_DIR / "Analyzer_Model_Metrics.csv",
    BASE_DIR / "analyzer_outputs" / "Analyzer_Model_Metrics.csv",
    BASE_DIR / "analyzer_outputs" / "analyzer_metrics.csv",
]
results_df = None
for metrics_path in metrics_candidates:
    if metrics_path.exists():
        try:
            results_df = pd.read_csv(metrics_path)
            break
        except Exception as exc:
            print(f"Could not read metrics file {metrics_path}: {exc}")

if results_df is None:
    results_df = pd.DataFrame({
        "Model": model_names,
        "Accuracy (%)": ["Not evaluated"] * len(model_names),
        "Precision (%)": ["Not available"] * len(model_names),
        "Recall (%)": ["Not available"] * len(model_names),
        "F1 Score (%)": ["Not available"] * len(model_names),
        "Training Time (sec)": ["Not available"] * len(model_names),
    })
else:
    if "Model" not in results_df.columns:
        first_col = results_df.columns[0] if len(results_df.columns) else None
        if first_col is not None:
            results_df = results_df.rename(columns={first_col: "Model"})
        else:
            results_df["Model"] = []
    results_df["Model"] = results_df["Model"].map(display_model_name)

    # Normalize common metric-column spellings into the dashboard schema.
    def find_metric_column(kind):
        for column in results_df.columns:
            name = str(column).strip().lower().replace("_", " ").replace("-", " ")
            if kind == "accuracy" and "accuracy" in name:
                return column
            if kind == "precision" and "precision" in name:
                return column
            if kind == "recall" and "recall" in name:
                return column
            if kind == "f1" and "f1" in name and "macro" not in name:
                return column
            if kind == "training" and "time" in name and ("train" in name or "fit" in name):
                return column
        return None

    metric_names = {
        "accuracy": "Accuracy (%)",
        "precision": "Precision (%)",
        "recall": "Recall (%)",
        "f1": "F1 Score (%)",
        "training": "Training Time (sec)",
    }
    for kind, standard_name in metric_names.items():
        existing = find_metric_column(kind)
        if existing and existing != standard_name:
            results_df = results_df.rename(columns={existing: standard_name})
        if standard_name not in results_df.columns:
            results_df[standard_name] = "Not available"

# If percentage metrics are stored as fractions (0-1), display percentages.
for percentage_column in ["Accuracy (%)", "Precision (%)", "Recall (%)", "F1 Score (%)"]:
    numeric_values = pd.to_numeric(results_df[percentage_column], errors="coerce")
    if numeric_values.notna().any() and numeric_values.dropna().max() <= 1.0:
        results_df[percentage_column] = numeric_values.map(
            lambda value: round(value * 100, 2) if pd.notna(value) else "Not available"
        )


# ============================================================
# 3. PREDICTION HELPERS
# ============================================================
def get_model(model_name):
    if model_name not in model_key_by_display:
        raise ValueError(f"Unknown model selected: {model_name}")
    return trained_models[model_key_by_display[model_name]]


def normalize_sentiment(value):
    """Normalize text sentiment labels; decode integer labels if an encoder exists."""
    # If the training notebook has a LabelEncoder, use it for numeric predictions.
    if isinstance(value, (int, np.integer)):
        encoder = globals().get("label_encoder", globals().get("le"))
        if encoder is not None and hasattr(encoder, "inverse_transform"):
            try:
                value = encoder.inverse_transform([int(value)])[0]
            except Exception:
                pass
        else:
            # Common mapping; change this if your training labels used another order.
            numeric_map = {0: "Negative", 1: "Neutral", 2: "Positive"}
            value = numeric_map.get(int(value), value)

    label = str(value).strip()
    lower = label.lower()
    if "positive" in lower:
        return "Positive"
    if "negative" in lower:
        return "Negative"
    if "neutral" in lower:
        return "Neutral"
    return label


def _model_input(model, texts):
    """Return the input format expected by the saved model."""
    try:
        model.predict(texts)
        return texts
    except Exception as raw_error:
        vectorizer = globals().get(
            "tfidf_vectorizer",
            globals().get("vectorizer", globals().get("tfidf"))
        )
        if vectorizer is None or not hasattr(vectorizer, "transform"):
            raise RuntimeError(
                "The selected model cannot accept raw text. Load the matching "
                "TF-IDF vectorizer or save the classifier and vectorizer together "
                "in a Pipeline. Original error: " + str(raw_error)
            ) from raw_error
        return vectorizer.transform(texts)


def predict_with_model(model, texts):
    """Predict using a Pipeline or a separately saved classifier/vectorizer."""
    model_input = _model_input(model, texts)
    return model.predict(model_input)


def confidence_percentages(model, texts):
    """Return one confidence percentage per text.

    predict_proba is a probability when the estimator supports it. For a model
    such as an uncalibrated LinearSVC, softmax(decision_function) is shown as an
    estimated confidence and is labelled accordingly in the UI.
    """
    model_input = _model_input(model, texts)
    if hasattr(model, "predict_proba"):
        probabilities = np.asarray(model.predict_proba(model_input))
        return np.max(probabilities, axis=1) * 100.0, "Probability confidence"
    if hasattr(model, "decision_function"):
        scores = np.asarray(model.decision_function(model_input))
        if scores.ndim == 1:
            scores = np.column_stack([-scores, scores])
        scores = scores - np.max(scores, axis=1, keepdims=True)
        probabilities = np.exp(scores)
        probabilities /= np.sum(probabilities, axis=1, keepdims=True)
        return np.max(probabilities, axis=1) * 100.0, "Estimated confidence"
    return np.full(len(texts), np.nan), "Confidence unavailable"



HISTORY_DB = Path(os.environ.get("SENTISCOPE_HISTORY_DB", str(BASE_DIR / "sentiscope_history.sqlite3")))


def init_history_db():
    HISTORY_DB.parent.mkdir(parents=True, exist_ok=True)
    with sqlite3.connect(HISTORY_DB) as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS analyses (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                input_text TEXT NOT NULL,
                model TEXT NOT NULL,
                sentiment TEXT NOT NULL,
                confidence TEXT,
                created_at TEXT NOT NULL
            )
        """)
        conn.execute("""
            CREATE TABLE IF NOT EXISTS app_users (
                username TEXT PRIMARY KEY COLLATE NOCASE,
                salt_hex TEXT NOT NULL,
                password_hash TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
        """)


def save_history_records(records):
    if not records:
        return
    created_at = datetime.now().astimezone().isoformat(timespec="seconds")
    rows = [(str(text), str(model), str(sentiment), str(confidence), created_at)
            for text, model, sentiment, confidence in records]
    with sqlite3.connect(HISTORY_DB) as conn:
        conn.executemany(
            "INSERT INTO analyses (input_text, model, sentiment, confidence, created_at) VALUES (?, ?, ?, ?, ?)",
            rows,
        )


def load_history_df():
    init_history_db()
    with sqlite3.connect(HISTORY_DB) as conn:
        return pd.read_sql_query(
            "SELECT created_at AS Timestamp, input_text AS 'Input text', model AS Model, sentiment AS 'Predicted sentiment', confidence AS Confidence FROM analyses ORDER BY id DESC LIMIT 500",
            conn,
        )


init_history_db()

def analyze_text(text, model_name):
    if text is None or not str(text).strip():
        return "ℹ️ Please enter some text.", ""
    try:
        model = get_model(model_name)
        clean_text = str(text)
        prediction = predict_with_model(model, [clean_text])[0]
        sentiment = normalize_sentiment(prediction)
        confidence, confidence_type = confidence_percentages(model, [clean_text])
        if np.isfinite(confidence[0]):
            confidence_text = f"{confidence_type}: {float(confidence[0]):.2f}%"
        else:
            confidence_text = "Confidence percentage is not available for this model."
        save_history_records([(clean_text, model_name, sentiment, confidence_text)])
        sentiment_icon = {
            "Positive": "😊",
            "Negative": "😟",
            "Neutral": "😐",
        }.get(sentiment, "💬")
        return f"{sentiment_icon} {sentiment}", f"🎯 {confidence_text}"
    except Exception as exc:
        return "⚠️ Prediction error", f"⚠️ {exc}"


def find_text_column(df):
    candidates = [
        "text", "tweet", "review", "comment", "message", "content",
        "sentence", "post", "feedback", "text_content", "clean_text"
    ]
    lookup = {str(col).strip().lower(): col for col in df.columns}
    for candidate in candidates:
        if candidate in lookup:
            return lookup[candidate]

    excluded = {
        "sentiment", "label", "target", "class", "category", "polarity",
        "predicted sentiment", "confidence (%)", "confidence"
    }
    for column in df.columns:
        name = str(column).strip().lower()
        if name not in excluded and (
            pd.api.types.is_object_dtype(df[column])
            or pd.api.types.is_string_dtype(df[column])
        ):
            return column
    return None


def find_label_column(df, text_column):
    """Find an optional ground-truth sentiment column for evaluation."""
    candidates = [
        "sentiment", "label", "target", "class", "category", "polarity",
        "actual sentiment", "true sentiment", "ground truth", "ground_truth"
    ]
    lookup = {str(col).strip().lower(): col for col in df.columns}
    for candidate in candidates:
        if candidate in lookup and lookup[candidate] != text_column:
            return lookup[candidate]
    return None


def _model_explanation_probabilities(model, texts):
    """Return score rows and the estimator's class order for LIME/SHAP."""
    texts = [str(text) for text in texts]
    model_input = _model_input(model, texts)
    classes = getattr(model, "classes_", None)
    if classes is None and hasattr(model, "named_steps"):
        for step in reversed(list(model.named_steps.values())):
            if hasattr(step, "classes_"):
                classes = step.classes_
                break
    if classes is None:
        encoder = globals().get("label_encoder", globals().get("le"))
        classes = getattr(encoder, "classes_", None) if encoder is not None else None

    if hasattr(model, "predict_proba"):
        scores = np.asarray(model.predict_proba(model_input), dtype=float)
    elif hasattr(model, "decision_function"):
        raw_scores = np.asarray(model.decision_function(model_input), dtype=float)
        if raw_scores.ndim == 1:
            raw_scores = np.column_stack([-raw_scores, raw_scores])
        raw_scores -= np.max(raw_scores, axis=1, keepdims=True)
        scores = np.exp(raw_scores)
        scores /= np.maximum(scores.sum(axis=1, keepdims=True), 1e-12)
    else:
        predictions = np.asarray(model.predict(model_input))
        if classes is None:
            classes = np.asarray([0, 1, 2])
        class_list = list(classes)
        scores = np.zeros((len(predictions), len(class_list)), dtype=float)
        for row_index, prediction in enumerate(predictions):
            match = next((i for i, value in enumerate(class_list) if str(value) == str(prediction)), None)
            if match is not None:
                scores[row_index, match] = 1.0

    if scores.ndim == 1:
        scores = scores.reshape(1, -1)
    if classes is None or len(classes) != scores.shape[1]:
        classes = np.arange(scores.shape[1])
    class_names = [normalize_sentiment(value) for value in classes]
    class_names = [name if name and name != "None" else f"Class {i}" for i, name in enumerate(class_names)]
    row_sums = scores.sum(axis=1, keepdims=True)
    scores = np.divide(scores, row_sums, out=np.full_like(scores, 1.0 / max(1, scores.shape[1])), where=row_sums > 0)
    return scores, class_names


def build_attribution_chart(attributions, model_name, method, target_label):
    """Render signed word contributions from real explainer output."""
    clean = [(str(token), float(value)) for token, value in attributions if np.isfinite(float(value))]
    clean = sorted(clean, key=lambda pair: abs(pair[1]), reverse=True)[:12]
    if not clean:
        clean = [("No token contributions returned", 0.0)]
    # Show the strongest items first; positive bars support the selected class.
    clean.reverse()
    tokens = [item[0] for item in clean]
    values = [item[1] for item in clean]
    colors = ["#37a779" if value >= 0 else "#e16b8b" for value in values]
    fig = go.Figure(go.Bar(
        x=values, y=tokens, orientation="h", marker={"color": colors, "line": {"color": "#ffffff", "width": 1}},
        text=[f"{value:+.4f}" for value in values], textposition="outside", cliponaxis=False,
        hovertemplate="<b>%{y}</b><br>Contribution: %{x:+.5f}<extra>Positive supports the selected class; negative opposes it.</extra>"
    ))
    fig.add_vline(x=0, line_color="#64748b", line_width=1)
    fig.update_layout(margin={"l": 100, "r": 35, "t": 85, "b": 55}, xaxis_title="Signed contribution to selected sentiment", yaxis_title="Word / feature", showlegend=False)
    fig.update_yaxes(autorange="reversed")
    return _style_interactive_plot(fig, f"{method} word impact · {target_label} · {model_name}", height=max(360, 34 * len(tokens) + 125))


def explain_model_text(text, model_name, method):
    """Compute a LIME or model-agnostic Kernel SHAP text explanation for the selected loaded model."""
    text = str(text or "").strip()
    if not text:
        raise gr.Error("Enter a review or comment before requesting an explanation.")
    model = get_model(model_name)
    predict_fn = lambda items: _model_explanation_probabilities(model, list(items))[0]
    try:
        probability_rows, class_names = _model_explanation_probabilities(model, [text])
        target_index = int(np.argmax(probability_rows[0]))
        target_label = class_names[target_index]
        if method == "LIME":
            try:
                from lime.lime_text import LimeTextExplainer
            except ImportError as exc:
                raise gr.Error("LIME is not installed. Install optional packages with: pip install lime shap pyspark") from exc
            explainer = LimeTextExplainer(class_names=class_names, random_state=42)
            token_count = max(1, len(re.findall(r"\w+", text)))
            explanation = explainer.explain_instance(
                text, predict_fn, labels=(target_index,), num_features=min(12, token_count), num_samples=400
            )
            attributions = explanation.as_list(label=target_index)
            note = f"LIME explanation for the model's predicted **{target_label}** class. Positive contributions support that class; negative contributions oppose it."
        elif method == "SHAP":
            try:
                import shap
            except ImportError as exc:
                raise gr.Error("SHAP is not installed. Install optional packages with: pip install lime shap pyspark") from exc
            tokens = re.findall(r"\b[\w'-]+\b", text)
            if not tokens:
                raise gr.Error("No words were found to explain in the supplied text.")
            counts = Counter(token.lower() for token in tokens)
            first_pos = {token.lower(): i for i, token in enumerate(tokens)}
            features = sorted(counts, key=lambda token: (-counts[token], first_pos[token]))[:10]
            # Coalition masks remove/include each selected word (all occurrences). The remaining words stay fixed.
            def predict_masked(mask_matrix):
                mask_matrix = np.asarray(mask_matrix, dtype=float)
                generated = []
                for mask in mask_matrix:
                    included = {features[i] for i, flag in enumerate(mask) if flag >= 0.5}
                    generated.append(" ".join(token for token in tokens if token.lower() not in features or token.lower() in included))
                return predict_fn(generated)
            background = np.zeros((1, len(features)), dtype=float)
            explainer = shap.KernelExplainer(predict_masked, background)
            nsamples = min(512, max(2, 2 ** len(features)))
            shap_values = explainer.shap_values(np.ones((1, len(features)), dtype=float), nsamples=nsamples, l1_reg=0.0)
            if isinstance(shap_values, list):
                contribution_values = np.asarray(shap_values[target_index], dtype=float).reshape(-1)
            else:
                values = np.asarray(shap_values, dtype=float)
                if values.ndim == 3:
                    contribution_values = values[0, :, target_index]
                elif values.ndim == 2:
                    contribution_values = values[0]
                else:
                    contribution_values = values.reshape(-1)
            attributions = list(zip(features[:len(contribution_values)], contribution_values.tolist()))
            note = f"Kernel SHAP values for the model's predicted **{target_label}** class. Up to 10 unique words were evaluated; words outside that set remain in the text as fixed context."
        else:
            raise gr.Error("Choose either LIME or SHAP.")

        attributions = sorted(attributions, key=lambda pair: abs(float(pair[1])), reverse=True)[:12]
        table = pd.DataFrame([
            {"Word / feature": str(token), "Contribution": round(float(value), 6),
             "Effect on selected class": "Supports prediction" if float(value) > 0 else ("Opposes prediction" if float(value) < 0 else "No measured change")}
            for token, value in attributions
        ])
        chart = build_attribution_chart(attributions, model_name, method, target_label)
        confidence_note = "probability scores" if hasattr(model, "predict_proba") else "decision-score estimates / model outputs"
        status = f"{note} Score source: {confidence_note}."
        return table, chart, status
    except gr.Error:
        raise
    except Exception as exc:
        raise gr.Error(f"{method} explanation failed: {type(exc).__name__}: {exc}") from exc


def _spark_predict_batch(model_obj, vectorizer_obj, batch_rows):
    """Predict one bounded Spark partition batch and return IDs, labels, and confidence values."""
    row_ids = [int(row[0]) for row in batch_rows]
    texts = [str(row[1]) for row in batch_rows]
    try:
        model_input = texts
        predictions = model_obj.predict(model_input)
    except Exception as raw_error:
        if vectorizer_obj is None or not hasattr(vectorizer_obj, "transform"):
            raise RuntimeError("Model cannot accept raw text in Spark workers; provide a paired TF-IDF vectorizer or a text Pipeline.") from raw_error
        model_input = vectorizer_obj.transform(texts)
        predictions = model_obj.predict(model_input)
    confidence = np.full(len(texts), np.nan, dtype=float)
    confidence_type = "Confidence unavailable"
    if hasattr(model_obj, "predict_proba"):
        try:
            confidence = np.max(np.asarray(model_obj.predict_proba(model_input), dtype=float), axis=1) * 100.0
            confidence_type = "Probability confidence"
        except Exception:
            pass
    if not np.isfinite(confidence).any() and hasattr(model_obj, "decision_function"):
        try:
            scores = np.asarray(model_obj.decision_function(model_input), dtype=float)
            if scores.ndim == 1:
                scores = np.column_stack([-scores, scores])
            scores -= np.max(scores, axis=1, keepdims=True)
            probabilities = np.exp(scores)
            probabilities /= np.maximum(probabilities.sum(axis=1, keepdims=True), 1e-12)
            confidence = np.max(probabilities, axis=1) * 100.0
            confidence_type = "Estimated confidence"
        except Exception:
            pass
    return [(row_id, prediction.item() if hasattr(prediction, "item") else prediction,
             float(value) if np.isfinite(value) else np.nan, confidence_type)
            for row_id, prediction, value in zip(row_ids, predictions, confidence)]


def spark_predict_csv(file_path, model, model_name):
    """Read/filter a CSV with Spark and distribute scikit-learn predictions across Spark workers."""
    try:
        from pyspark.sql import SparkSession, functions as F
    except ImportError as exc:
        raise gr.Error("PySpark is not installed. Install it with `pip install pyspark` and ensure Java is available, then restart the app.") from exc

    spark = globals().get("spark")
    owns_spark = spark is None
    try:
        if owns_spark:
            spark = (SparkSession.builder.appName("SentiScopeDatasetAnalysis")
                     .master(os.environ.get("SENTISCOPE_SPARK_MASTER", "local[*]"))
                     .config("spark.sql.execution.arrow.pyspark.enabled", "true")
                     .getOrCreate())
        spark_df = spark.read.option("header", "true").option("inferSchema", "false").csv(str(file_path))
        columns = list(spark_df.columns)
        if not columns:
            raise gr.Error("The uploaded CSV has no header columns.")
        empty_df = pd.DataFrame(columns=columns)
        text_column = find_text_column(empty_df)
        if text_column is None:
            raise gr.Error("Could not find a text column. Include Text, Review, Tweet, Comment, Message, or Content.")
        label_column = find_label_column(empty_df, text_column)
        row_id = "__sentiscope_row_id"
        while row_id in columns:
            row_id = "_" + row_id
        quote_col = lambda name: F.col("`" + str(name).replace("`", "``") + "`")
        text_expr = quote_col(text_column).cast("string")
        clean_df = (spark_df.withColumn(row_id, F.monotonically_increasing_id())
                    .filter(text_expr.isNotNull() & (F.length(F.trim(text_expr)) > 0)).cache())
        if clean_df.limit(1).count() == 0:
            raise gr.Error(f"No non-empty text was found in '{text_column}'.")
        vectorizer = globals().get("tfidf_vectorizer", globals().get("vectorizer", globals().get("tfidf")))
        broadcast_models = spark.sparkContext.broadcast((model, vectorizer))
        def predict_partition(iterator):
            model_obj, vectorizer_obj = broadcast_models.value
            batch = []
            for row in iterator:
                batch.append((int(row[0]), str(row[1])))
                if len(batch) >= 256:
                    yield from _spark_predict_batch(model_obj, vectorizer_obj, batch)
                    batch = []
            if batch:
                yield from _spark_predict_batch(model_obj, vectorizer_obj, batch)
        prediction_rows = (clean_df.select(quote_col(row_id), text_expr)
                           .rdd.mapPartitions(predict_partition).collect())
        prediction_rows.sort(key=lambda row: row[0])
        if not prediction_rows:
            raise gr.Error("Spark did not find any text records to evaluate.")
        try:
            result_df = clean_df.orderBy(quote_col(row_id)).drop(row_id).toPandas()
        except Exception:
            result_df = pd.DataFrame([row.asDict(recursive=True) for row in clean_df.orderBy(quote_col(row_id)).drop(row_id).collect()], columns=columns)
        predictions = [row[1] for row in prediction_rows]
        confidence_values = np.asarray([row[2] for row in prediction_rows], dtype=float)
        confidence_type = prediction_rows[0][3]
        clean_df.unpersist()
        broadcast_models.unpersist(blocking=False)
        return result_df, text_column, label_column, predictions, confidence_values, confidence_type
    except gr.Error:
        raise
    except Exception as exc:
        raise gr.Error(f"PySpark dataset processing failed ({type(exc).__name__}): {exc}. Check Java, Spark configuration, and model/vectorizer availability.") from exc
    finally:
        if owns_spark and spark is not None:
            try:
                spark.stop()
            except Exception:
                pass


def build_uploaded_performance_chart(metrics_df):
    """Plot only metrics calculated from the latest uploaded CSV's valid ground-truth labels."""
    metric_order = ["Accuracy", "Macro Precision", "Macro Recall", "Macro F1-Score"]
    values_by_name = {}
    if metrics_df is not None and not metrics_df.empty and {"Dataset metric", "Value"}.issubset(metrics_df.columns):
        for _, row in metrics_df.iterrows():
            name = str(row["Dataset metric"])
            if name in metric_order:
                try:
                    values_by_name[name] = float(str(row["Value"]).replace("%", "").strip())
                except (TypeError, ValueError):
                    pass
    fig = go.Figure()
    present = [name for name in metric_order if name in values_by_name]
    if present:
        colors = ["#6558c8", "#38a6d7", "#36a77d", "#e47f9d"]
        fig.add_trace(go.Bar(x=present, y=[values_by_name[name] for name in present],
            marker={"color": colors[:len(present)], "line": {"color": "#ffffff", "width": 2}},
            text=[f"{values_by_name[name]:.2f}%" for name in present], textposition="outside", cliponaxis=False,
            hovertemplate="<b>%{x}</b><br>Actual uploaded-dataset score: %{y:.2f}%<extra>From ground-truth labels</extra>"))
        fig.update_layout(showlegend=False, bargap=.45, yaxis={"title": "Score (%)", "range": [0, 108]})
    else:
        fig.add_annotation(text="Upload a CSV with text and ground-truth labels to calculate real dataset metrics.", x=.5, y=.5, xref="paper", yref="paper", showarrow=False, font={"size": 13, "color": "#475569"})
        fig.update_xaxes(visible=False); fig.update_yaxes(visible=False)
    return _style_interactive_plot(fig, "Actual uploaded-dataset evaluation", height=410)


def _style_interactive_plot(fig, title, height=420):
    """Style responsive Plotly charts with hover/touch labels and update transitions."""
    fig.update_layout(
        template="plotly_white", title={"text":title,"x":0.025,"xanchor":"left"},
        font={"family":"Inter, Segoe UI, Arial, sans-serif","size":13,"color":"#1e293b"},
        paper_bgcolor="#ffffff",plot_bgcolor="#ffffff",height=height,
        margin={"l":55,"r":28,"t":76,"b":64},
        hoverlabel={"bgcolor":"#ffffff","bordercolor":"#94a3b8","font":{"size":14,"color":"#0f172a"}},
        transition={"duration":500,"easing":"cubic-in-out"},
        dragmode=False,showlegend=True,hovermode="closest",clickmode="event+select",
    )
    for trace in fig.data:
        if getattr(trace,"type",None)=="bar":
            trace.selected={"marker":{"color":"#0f172a"}}
            trace.unselected={"marker":{"opacity":.42}}
    fig.update_xaxes(showgrid=False,zeroline=False,automargin=True)
    fig.update_yaxes(showgrid=True,gridcolor="#e8edf5",zeroline=False,automargin=True)
    return fig


def build_sentiment_summary_chart(summary_df):
    """Show observed class counts; Plotly enables per-bar hover/touch feedback."""
    sentiments = summary_df["Sentiment"].astype(str).tolist()
    counts = pd.to_numeric(summary_df["Count"], errors="coerce").fillna(0).to_numpy(dtype=float)
    percentages = pd.to_numeric(summary_df["Percentage (%)"], errors="coerce").fillna(0).to_numpy(dtype=float)
    sentiment_colors = {"Positive": "#86efac", "Negative": "#fda4af", "Neutral": "#93c5fd"}
    colors = [sentiment_colors.get(name, "#64748b") for name in sentiments]
    if go is not None:
        labels=[f"{int(count)} · {share:.2f}%" for count,share in zip(counts,percentages)]
        fig=go.Figure(go.Bar(x=sentiments,y=counts,marker={"color":colors,"line":{"color":"#ffffff","width":2}},
            text=labels,textposition="outside",cliponaxis=False,customdata=percentages,
            hovertemplate="<b>%{x}</b><br>Records: %{y:,.0f}<br>Share: %{customdata:.2f}%<extra>Tap/hover for details</extra>"))
        fig.update_layout(bargap=.42,showlegend=False,yaxis_title="Number of records",xaxis_title="Sentiment",yaxis={"rangemode":"tozero","range":[0,max(1,float(counts.max())*1.28)]})
        return _style_interactive_plot(fig,"Sentiment Counts and Percentages",height=360)

    fig, ax = plt.subplots(figsize=(7.5, 3.6))
    fig.patch.set_facecolor("#ffffff")
    bars = ax.bar(np.arange(len(sentiments)), counts, width=0.56, color=colors, zorder=3)
    for bar, count, percentage in zip(bars, counts, percentages):
        ax.annotate(
            f"{int(count)}  ·  {percentage:.2f}%",
            (bar.get_x() + bar.get_width() / 2, count),
            xytext=(0, 5), textcoords="offset points", ha="center", va="bottom",
            fontsize=9, fontweight="bold", color="#263248",
        )
    ax.set_title("Sentiment Counts and Percentages", loc="left", fontsize=11,
                 fontweight="bold", color="#172554", pad=10)
    ax.set_ylabel("Number of records", fontsize=9, color="#475569")
    ax.set_xticks(np.arange(len(sentiments)))
    ax.set_xticklabels(sentiments, fontsize=9)
    ax.set_ylim(0, max(1, float(counts.max()) * 1.22))
    ax.grid(axis="y", color="#e8edf5", linewidth=0.8, zorder=0)
    ax.set_facecolor("#ffffff")
    ax.spines[["top", "right"]].set_visible(False)
    ax.spines[["left", "bottom"]].set_color("#cbd5e1")
    ax.tick_params(colors="#475569")
    fig.tight_layout(pad=1.4)
    return fig


def analyze_csv(file, model_name, use_spark=False):
    if file is None:
        raise gr.Error("Please upload a CSV dataset first.")

    try:
        file_path = file.name if hasattr(file, "name") else str(file)
        model = get_model(model_name)
        processing_started = time.perf_counter()
        if use_spark:
            df, text_column, label_column, predictions, confidences, confidence_type = spark_predict_csv(file_path, model, model_name)
            results = df.copy()
            texts = results[text_column].astype(str).tolist()
            processing_engine = "Apache Spark (PySpark)"
        else:
            df = pd.read_csv(file_path)
            if df.empty:
                raise gr.Error("The uploaded CSV contains no records.")
            text_column = find_text_column(df)
            if text_column is None:
                raise gr.Error("Could not find a text column. Include Text, Review, Tweet, Comment, Message, or Content.")
            label_column = find_label_column(df, text_column)
            valid_mask = df[text_column].notna() & df[text_column].astype(str).str.strip().ne("")
            results = df.loc[valid_mask].copy()
            if results.empty:
                raise gr.Error(f"No non-empty text was found in '{text_column}'.")
            texts = results[text_column].astype(str).tolist()
            predictions = predict_with_model(model, texts)
            confidences, confidence_type = confidence_percentages(model, texts)
            processing_engine = "Pandas + scikit-learn"
        processing_seconds = time.perf_counter() - processing_started
        if len(predictions) != len(results):
            raise RuntimeError("Prediction rows did not align with uploaded text rows.")

        results["Predicted Sentiment"] = [normalize_sentiment(prediction) for prediction in predictions]
        results["Confidence (%)"] = [round(float(value), 2) if np.isfinite(value) else "Not available" for value in confidences]
        save_history_records([
            (text, model_name, sentiment,
             f"{confidence_type}: {float(confidence):.2f}%" if np.isfinite(confidence) else "Not available")
            for text, sentiment, confidence in zip(texts, results["Predicted Sentiment"], confidences)
        ])

        metrics_rows = [
            ["Model", display_model_name(model_name)],
            ["Rows analyzed", str(len(results))],
            ["Processing engine", processing_engine],
            ["Prediction/processing time (sec)", f"{processing_seconds:.3f}"],
            ["Confidence type", confidence_type],
        ]
        if label_column is not None:
            actual = results[label_column].map(normalize_sentiment)
            valid_labels = actual.isin(["Positive", "Negative", "Neutral"])
            if valid_labels.any():
                actual_valid = actual.loc[valid_labels]
                predicted_valid = results.loc[valid_labels, "Predicted Sentiment"]
                score_labels = ["Positive", "Negative", "Neutral"]
                accuracy = accuracy_score(actual_valid, predicted_valid) * 100.0
                precision_values, recall_values, f1_values, _ = precision_recall_fscore_support(
                    actual_valid, predicted_valid, labels=score_labels, average=None, zero_division=0
                )
                macro_precision = precision_recall_fscore_support(actual_valid, predicted_valid, labels=score_labels, average="macro", zero_division=0)[0] * 100.0
                macro_recall = precision_recall_fscore_support(actual_valid, predicted_valid, labels=score_labels, average="macro", zero_division=0)[1] * 100.0
                macro_f1 = f1_score(actual_valid, predicted_valid, labels=score_labels, average="macro", zero_division=0) * 100.0
                metrics_rows.extend([
                    ["Ground-truth column", str(label_column)],
                    ["Labeled rows evaluated", str(int(valid_labels.sum()))],
                    ["Accuracy", f"{accuracy:.2f}%"],
                    ["Macro Precision", f"{macro_precision:.2f}%"],
                    ["Macro Recall", f"{macro_recall:.2f}%"],
                    ["Macro F1-Score", f"{macro_f1:.2f}%"],
                ])
                for index, label in enumerate(score_labels):
                    metrics_rows.extend([
                        [f"{label} Precision", f"{precision_values[index] * 100.0:.2f}%"],
                        [f"{label} Recall", f"{recall_values[index] * 100.0:.2f}%"],
                        [f"{label} F1-Score", f"{f1_values[index] * 100.0:.2f}%"],
                    ])
            else:
                metrics_rows.extend([["Ground-truth column", str(label_column)], ["Evaluation", "No valid Positive/Negative/Neutral ground-truth labels were found."]])
        else:
            metrics_rows.append(["Evaluation", "No ground-truth label column found. Predictions and sentiment counts are available, but accuracy, precision, recall, and F1 cannot be calculated."])
        dataset_metrics_df = pd.DataFrame(metrics_rows, columns=["Dataset metric", "Value"])
        uploaded_performance_chart = build_uploaded_performance_chart(dataset_metrics_df)

        positive_df = results[results["Predicted Sentiment"] == "Positive"].reset_index(drop=True)
        negative_df = results[results["Predicted Sentiment"] == "Negative"].reset_index(drop=True)
        neutral_df = results[results["Predicted Sentiment"] == "Neutral"].reset_index(drop=True)
        total = len(results)
        counts = results["Predicted Sentiment"].value_counts()
        summary_df = pd.DataFrame({
            "Sentiment": ["Positive", "Negative", "Neutral"],
            "Count": [int(counts.get("Positive", 0)), int(counts.get("Negative", 0)), int(counts.get("Neutral", 0))],
        })
        summary_df["Percentage (%)"] = summary_df["Count"].astype(float).div(total).mul(100).round(2)
        summary_chart = build_sentiment_summary_chart(summary_df)
        with tempfile.NamedTemporaryFile(prefix="analyzer_predictions_", suffix=".csv", delete=False) as temp_file:
            output_path = temp_file.name
        results.to_csv(output_path, index=False)
        return (
            positive_df, negative_df, neutral_df, summary_df, results.reset_index(drop=True),
            dataset_metrics_df, output_path, summary_chart, dataset_metrics_df, uploaded_performance_chart,
        )
    except gr.Error:
        raise
    except Exception as exc:
        raise gr.Error(f"Dataset analysis failed: {type(exc).__name__}: {exc}") from exc


# ============================================================
# 4. DASHBOARD METRIC CARDS
# ============================================================
def format_metric(value):
    try:
        numeric = float(value)
        if 0 <= numeric <= 1:
            numeric *= 100
        return f"{numeric:.2f}%"
    except (TypeError, ValueError):
        return str(value)


def build_dashboard_chart(metrics_df):
    """Plot saved metrics; Plotly adds hover/touch feedback and animated updates."""
    score_columns = ["Accuracy (%)", "Precision (%)", "Recall (%)", "F1 Score (%)"]
    if go is not None:
        available=[column for column in score_columns if column in metrics_df.columns]
        names=metrics_df.get("Model",pd.Series(dtype=str)).fillna("Unknown model").astype(str).tolist()
        palette=["#8b5cf6","#0ea5e9","#10b981","#f97316","#db2777","#eab308"]
        fig=make_subplots(rows=2,cols=1,specs=[[{"type":"xy"}],[{"type":"domain"}]],row_heights=[.67,.33],vertical_spacing=.20,subplot_titles=("Model Score Comparison","Training Time Share"))
        valid_cols=[];maxval=0.0
        for col in available:
            vals=_percentage_series(metrics_df,col).to_numpy(dtype=float)
            if np.isfinite(vals).any():valid_cols.append((col,vals));maxval=max(maxval,float(np.nanmax(vals)))
        for idx,name in enumerate(names):
            xs=[];ys=[]
            for col,vals in valid_cols:
                xs.append(col.replace(" (%)",""));ys.append(float(vals[idx]) if idx<len(vals) and np.isfinite(vals[idx]) else None)
            if any(v is not None for v in ys):
                fig.add_trace(go.Bar(x=xs,y=ys,name=name,marker={"color":palette[idx%len(palette)],"line":{"color":"#ffffff","width":1}},
                    text=[f"{v:.1f}%" if v is not None else "" for v in ys],textposition="outside",cliponaxis=False,
                    hovertemplate="<b>%{fullData.name}</b><br>%{x}: %{y:.2f}%<extra>Touch or hover to highlight</extra>"),row=1,col=1)
        time_col="Training Time (sec)"
        if time_col in metrics_df.columns and names:
            times=pd.to_numeric(metrics_df[time_col],errors="coerce").to_numpy(dtype=float)
            keep=np.isfinite(times)&(times>0)
            if keep.any():
                pie_names=np.asarray(names)[keep].tolist();pie_vals=times[keep].tolist();pie_colors=[palette[i%len(palette)] for i,k in enumerate(keep) if k]
                fig.add_trace(go.Pie(labels=pie_names,values=pie_vals,marker={"colors":pie_colors,"line":{"color":"#ffffff","width":2}},hole=.34,textinfo="label+percent",
                    hovertemplate="<b>%{label}</b><br>Training time: %{value:.3g} seconds<br>Share: %{percent}<extra>Touch or hover for details</extra>",showlegend=False),row=2,col=1)
        fig.update_layout(barmode="group",bargap=.24,bargroupgap=.12,legend={"orientation":"h","y":1.18,"x":0},margin={"l":50,"r":28,"t":110,"b":50},height=690)
        fig.update_yaxes(title_text="Score (%)",range=[0,max(110,maxval+18)],row=1,col=1)
        fig.update_xaxes(title_text="Evaluation metric",row=1,col=1)
        return _style_interactive_plot(fig,"Model Evaluation · Interactive Charts",height=690)

    display_columns = [column for column in score_columns if column in metrics_df.columns]
    labels = metrics_df.get("Model", pd.Series(dtype=str)).fillna("Unknown model").astype(str).tolist()
    fig, (score_ax, time_ax) = plt.subplots(
        2, 1, figsize=(9, 7), gridspec_kw={"height_ratios": [1.5, 1]}
    )
    fig.patch.set_facecolor("#ffffff")
    palette = ["#a5b4fc", "#fdba74", "#86efac", "#c4b5fd", "#f9a8d4", "#67e8f9"]
    model_colors = [palette[index % len(palette)] for index in range(len(labels))]

    def numeric_values(column):
        return pd.to_numeric(
            metrics_df[column].astype(str).str.replace("%", "", regex=False).str.strip(),
            errors="coerce",
        )

    valid_score_columns = [(column, numeric_values(column)) for column in display_columns]
    valid_score_columns = [(column, series) for column, series in valid_score_columns if series.notna().any()]

    if labels and valid_score_columns:
        x = np.arange(len(valid_score_columns))
        group_width = 0.68
        width = group_width / max(1, len(labels))
        for model_index, (model_name, color) in enumerate(zip(labels, model_colors)):
            values = [series.iloc[model_index] if model_index < len(series) else np.nan
                      for _, series in valid_score_columns]
            values = np.asarray(values, dtype=float)
            offset = (model_index - (len(labels) - 1) / 2) * width
            bars = score_ax.bar(x + offset, values, width * 0.76, label=model_name,
                                color=color, zorder=3)
            for bar, value in zip(bars, values):
                if np.isfinite(value):
                    score_ax.annotate(f"{value:.2f}%", (bar.get_x() + bar.get_width()/2, value),
                                      xytext=(0, 4 + model_index * 12), textcoords="offset points", ha="center",
                                      va="bottom", fontsize=7, color="#263248")
        score_ax.set_title("Model Score Comparison", loc="left", fontsize=11, fontweight="bold", color="#172554", pad=9)
        score_ax.set_ylabel("Score (%)", color="#475569")
        score_ax.set_xticks(x)
        score_ax.set_xticklabels([column.replace(" (%)", "") for column, _ in valid_score_columns], fontsize=8)
        max_value = max((series.max() for _, series in valid_score_columns), default=100)
        score_ax.set_ylim(bottom=0, top=max(120, max_value + 28))
        score_ax.legend(frameon=False, fontsize=8, ncol=min(4, max(1, len(labels))),
                        loc="upper center", bbox_to_anchor=(0.5, 1.0), borderaxespad=0.2)
        score_ax.grid(axis="y", color="#e8edf5", linewidth=0.8, zorder=0)
    else:
        score_ax.text(0.5, 0.5, "Evaluation scores are not available", ha="center", va="center", color="#64748b")
        score_ax.set_title("Model Score Comparison", loc="left", fontsize=11, fontweight="bold", color="#172554")

    time_col = "Training Time (sec)"
    if labels and time_col in metrics_df.columns:
        times = numeric_values(time_col)
        valid = times.notna() & (times > 0)
        if valid.any():
            time_labels = [label for label, keep in zip(labels, valid) if keep]
            time_values = times[valid].to_numpy(dtype=float)
            time_colors = [color for color, keep in zip(model_colors, valid) if keep]
            wedges, _, _ = time_ax.pie(
                time_values, colors=time_colors, startangle=90, counterclock=False,
                autopct="%1.1f%%", pctdistance=0.72,
                textprops={"color": "white", "fontsize": 8, "weight": "bold"},
                wedgeprops={"linewidth": 1.5, "edgecolor": "white"},
            )
            time_ax.set_title("Training Time Share", loc="left", fontsize=11, fontweight="bold", color="#172554", pad=9)
            legend_labels = [f"{name} — {value:.2f} sec" for name, value in zip(time_labels, time_values)]
            time_ax.legend(wedges, legend_labels, title="Model · training time", frameon=False,
                           fontsize=8, title_fontsize=8, loc="center left", bbox_to_anchor=(1.0, 0.5))
        else:
            time_ax.text(0.5, 0.5, "Training time is not available", ha="center", va="center", color="#64748b")
            time_ax.set_title("Training Time Share", loc="left", fontsize=11, fontweight="bold", color="#172554")
    else:
        time_ax.text(0.5, 0.5, "Training time is not available", ha="center", va="center", color="#64748b")
        time_ax.set_title("Training Time Share", loc="left", fontsize=11, fontweight="bold", color="#172554")

    for ax in (score_ax, time_ax):
        ax.set_facecolor("#ffffff")
        ax.spines[["top", "right"]].set_visible(False)
        ax.spines[["left", "bottom"]].set_color("#cbd5e1")
        ax.tick_params(colors="#475569")
    time_ax.set_aspect("equal", adjustable="box")
    fig.subplots_adjust(hspace=0.48, left=0.1, right=0.76, top=0.94, bottom=0.08)
    return fig


def _percentage_series(frame, column):
    if column not in frame.columns:
        return pd.Series(np.nan, index=frame.index, dtype=float)
    values = pd.to_numeric(frame[column].astype(str).str.replace("%", "", regex=False).str.strip(), errors="coerce")
    fractional_scores = values.notna() & values.ge(0) & values.le(1)
    values = values.where(~fractional_scores, values * 100)
    return values


def build_model_accuracy_chart(metrics_df):
    """A compact accuracy ranking with touch/hover values and bar highlighting."""
    if go is not None and "Model" in metrics_df.columns and "Accuracy (%)" in metrics_df.columns:
        values=_percentage_series(metrics_df,"Accuracy (%)");valid=values.notna()
        if valid.any():
            names=metrics_df.loc[valid,"Model"].astype(str).tolist();scores=values.loc[valid].to_numpy(dtype=float)
            palette=["#8b5cf6","#0ea5e9","#10b981","#f97316","#db2777","#eab308"]
            fig=go.Figure(go.Bar(x=scores,y=names,orientation="h",marker={"color":[palette[i%len(palette)] for i in range(len(names))],"line":{"color":"#ffffff","width":2}},
                text=[f"{v:.2f}%" for v in scores],textposition="outside",cliponaxis=False,
                hovertemplate="<b>%{y}</b><br>Accuracy: %{x:.2f}%<extra>Touch or hover to highlight</extra>"))
            fig.update_layout(showlegend=False,xaxis_title="Accuracy (%)",yaxis={"categoryorder":"total ascending"},xaxis={"range":[0,max(108,float(scores.max())*1.18)]})
            return _style_interactive_plot(fig,"Accuracy by Model · Touch or hover on a bar",height=max(310,100+58*len(names)))
    fig, ax = plt.subplots(figsize=(7.2, max(2.6, 0.52 * max(1, len(metrics_df)))))
    fig.patch.set_facecolor("#ffffff"); ax.set_facecolor("#ffffff")
    if "Model" not in metrics_df.columns or "Accuracy (%)" not in metrics_df.columns:
        ax.text(0.5, 0.5, "Accuracy values are not available", ha="center", va="center", color="#475569")
        ax.set_axis_off(); return fig
    values = _percentage_series(metrics_df, "Accuracy (%)")
    valid = values.notna()
    if not valid.any():
        ax.text(0.5, 0.5, "Accuracy values are not available", ha="center", va="center", color="#475569")
        ax.set_axis_off(); return fig
    names = metrics_df.loc[valid, "Model"].astype(str).tolist()
    scores = values.loc[valid].to_numpy(dtype=float)
    palette = ["#a5b4fc", "#fdba74", "#86efac", "#f9a8d4", "#93c5fd"]
    bars = ax.barh(names[::-1], scores[::-1], color=[palette[i % len(palette)] for i in range(len(scores))][::-1], height=0.58)
    for bar, score in zip(bars, scores[::-1]):
        ax.text(min(score + 1, 99), bar.get_y()+bar.get_height()/2, f"{score:.2f}%", va="center", ha="left", fontsize=11, color="#1e293b", fontweight="bold")
    ax.set_xlim(0, max(108, min(130, float(scores.max())+12)))
    ax.set_title("Accuracy by Model", loc="left", fontsize=14, fontweight="bold", color="#172554", pad=12)
    ax.set_xlabel("Accuracy (%)", color="#475569"); ax.grid(axis="x", color="#e8edf5", linewidth=.8); ax.set_axisbelow(True)
    ax.spines[["top", "right", "left"]].set_visible(False); ax.spines["bottom"].set_color("#cbd5e1"); ax.tick_params(axis="y", length=0, labelsize=11, colors="#334155")
    fig.tight_layout(); return fig


def build_performance_heatmap(metrics_df):
    """Pastel annotated heatmap of actual percentage metrics; missing values stay blank."""
    columns = [c for c in ["Accuracy (%)", "Precision (%)", "Recall (%)", "F1 Score (%)"] if c in metrics_df.columns]
    fig, ax = plt.subplots(figsize=(8.2, max(2.8, 0.62 * max(1, len(metrics_df)))))
    fig.patch.set_facecolor("#ffffff"); ax.set_facecolor("#ffffff")
    if not columns or "Model" not in metrics_df.columns:
        ax.text(0.5, 0.5, "Percentage metrics are not available", ha="center", va="center", color="#475569"); ax.set_axis_off(); return fig
    values = np.column_stack([_percentage_series(metrics_df, col).to_numpy(dtype=float) for col in columns])
    if not np.isfinite(values).any():
        ax.text(0.5, 0.5, "Percentage metrics are not available", ha="center", va="center", color="#475569"); ax.set_axis_off(); return fig
    masked = np.ma.masked_invalid(values)
    image = ax.imshow(masked, cmap="Pastel1", vmin=0, vmax=100, aspect="auto")
    names = metrics_df["Model"].fillna("Unknown").astype(str).tolist()
    ax.set_xticks(np.arange(len(columns)), [c.replace(" (%)", "") for c in columns], fontsize=11)
    ax.set_yticks(np.arange(len(names)), names, fontsize=11)
    for row in range(values.shape[0]):
        for col in range(values.shape[1]):
            val = values[row, col]
            ax.text(col, row, f"{val:.1f}%" if np.isfinite(val) else "—", ha="center", va="center", color="#172554", fontsize=10, fontweight="bold")
    ax.set_title("Model Metric Heatmap", loc="left", fontsize=14, fontweight="bold", color="#172554", pad=12)
    ax.set_xticks(np.arange(-.5, len(columns), 1), minor=True); ax.set_yticks(np.arange(-.5, len(names), 1), minor=True)
    ax.grid(which="minor", color="white", linestyle="-", linewidth=3); ax.tick_params(which="minor", bottom=False, left=False)
    fig.colorbar(image, ax=ax, fraction=.04, pad=.04, label="Score (%)"); fig.tight_layout(); return fig


def build_performance_score_chart(metrics_df):
    """Grouped comparison of saved scores with per-bar hover/touch highlighting."""
    columns=[("Accuracy (%)","#8b5cf6"),("Precision (%)","#0ea5e9"),("Recall (%)","#10b981"),("F1 Score (%)","#f97316")]
    if go is not None and "Model" in metrics_df.columns:
        names=metrics_df["Model"].fillna("Unknown").astype(str).tolist();fig=go.Figure();maxval=0.0
        for col,color in columns:
            if col not in metrics_df.columns:continue
            vals=_percentage_series(metrics_df,col).to_numpy(dtype=float)
            if not np.isfinite(vals).any():continue
            maxval=max(maxval,float(np.nanmax(vals)))
            fig.add_trace(go.Bar(x=names,y=[float(v) if np.isfinite(v) else None for v in vals],name=col.replace(" (%)",""),marker={"color":color,"line":{"color":"#ffffff","width":1}},
                text=[f"{v:.1f}%" if np.isfinite(v) else "" for v in vals],textposition="outside",cliponaxis=False,
                hovertemplate="<b>%{x}</b><br>"+col.replace(" (%)","")+": %{y:.2f}%<extra>Touch or hover to highlight</extra>"))
        if fig.data:
            fig.update_layout(barmode="group",bargap=.26,bargroupgap=.12,yaxis={"range":[0,max(110,maxval+18)],"title":"Score (%)"},xaxis_title="Model",legend={"orientation":"h","y":1.16,"x":0})
            return _style_interactive_plot(fig,"Accuracy, Precision, Recall & F1 · Interactive",height=490)
    columns=[(name,color) for name,color in columns if name in metrics_df.columns]
    columns=[(name,color) for name,color in columns if name in metrics_df.columns]
    fig,ax=plt.subplots(figsize=(max(8,min(13,4+0.85*max(1,len(metrics_df)))),5.0))
    fig.patch.set_facecolor("#ffffff");ax.set_facecolor("#ffffff")
    if not columns or "Model" not in metrics_df.columns or metrics_df.empty:
        ax.text(.5,.5,"Saved percentage metrics are not available",ha="center",va="center",color="#475569");ax.set_axis_off();return fig
    names=metrics_df["Model"].fillna("Unknown").astype(str).tolist();x=np.arange(len(names));width=min(.19,.72/len(columns));allvals=[]
    for idx,(column,color) in enumerate(columns):
        values=_percentage_series(metrics_df,column).to_numpy(dtype=float);allvals.extend(values[np.isfinite(values)].tolist())
        offset=(idx-(len(columns)-1)/2)*width;valid=np.isfinite(values)
        bars=ax.bar(x[valid]+offset,values[valid],width,label=column.replace(" (%)",""),color=color,edgecolor="#ffffff",linewidth=.7)
        for bar,value in zip(bars,values[valid]):
            ax.text(bar.get_x()+bar.get_width()/2,value+1.1,f"{value:.1f}%",ha="center",va="bottom",fontsize=8,color="#1e293b",fontweight="bold",rotation=0)
    ceiling=max(108,(max(allvals)+15) if allvals else 108);ax.set_ylim(0,ceiling)
    ax.set_xticks(x,names,rotation=15,ha="right",fontsize=10)
    ax.set_ylabel("Score (%)",color="#475569");ax.set_title("Model Score Comparison",loc="left",fontsize=14,fontweight="bold",color="#172554",pad=14)
    ax.grid(axis="y",color="#e8edf5",linewidth=.8);ax.set_axisbelow(True);ax.legend(ncols=max(1,len(columns)),loc="upper center",bbox_to_anchor=(.5,1.02),frameon=False,fontsize=9)
    ax.spines[["top","right","left"]].set_visible(False);ax.spines["bottom"].set_color("#cbd5e1");ax.tick_params(axis="y",colors="#475569")
    fig.tight_layout();return fig


def build_training_time_chart(metrics_df):
    """Training-time comparison with exact value labels and touch/hover emphasis."""
    if go is not None and "Training Time (sec)" in metrics_df.columns and "Model" in metrics_df.columns:
        vals=pd.to_numeric(metrics_df["Training Time (sec)"],errors="coerce").to_numpy(dtype=float);names=metrics_df["Model"].fillna("Unknown").astype(str).to_numpy();valid=np.isfinite(vals)&(vals>=0)
        if valid.any():
            v=vals[valid];n=names[valid];palette=["#8b5cf6","#0ea5e9","#10b981","#f97316","#db2777","#eab308"]
            fig=go.Figure(go.Bar(x=v,y=n,orientation="h",marker={"color":[palette[i%len(palette)] for i in range(len(v))],"line":{"color":"#ffffff","width":2}},
                text=[f"{x:.3g} s" for x in v],textposition="outside",cliponaxis=False,
                hovertemplate="<b>%{y}</b><br>Training time: %{x:.4g} seconds<extra>Touch or hover to highlight</extra>"))
            fig.update_layout(showlegend=False,xaxis_title="Training Time (seconds)",yaxis={"categoryorder":"total ascending"},xaxis={"range":[0,max(.1,float(v.max())*1.24)]})
            return _style_interactive_plot(fig,"Training Time by Model · Interactive",height=max(310,100+58*len(n)))
    fig,ax=plt.subplots(figsize=(8.5,max(3.0,.72*max(1,len(metrics_df)))))
    fig.patch.set_facecolor("#ffffff");ax.set_facecolor("#ffffff")
    if "Training Time (sec)" not in metrics_df.columns or "Model" not in metrics_df.columns or metrics_df.empty:
        ax.text(.5,.5,"Training-time values are not available",ha="center",va="center",color="#475569");ax.set_axis_off();return fig
    values=pd.to_numeric(metrics_df["Training Time (sec)"],errors="coerce").to_numpy(dtype=float)
    names=metrics_df["Model"].fillna("Unknown").astype(str).to_numpy();valid=np.isfinite(values)&(values>=0)
    if not valid.any():
        ax.text(.5,.5,"Training-time values are not available",ha="center",va="center",color="#475569");ax.set_axis_off();return fig
    vals=values[valid][::-1];labs=names[valid][::-1];palette=["#a78bfa","#60a5fa","#34d399","#fb7185","#fbbf24","#22d3ee"]
    bars=ax.barh(labs,vals,color=[palette[i%len(palette)] for i in range(len(vals))],height=.58,edgecolor="#ffffff")
    maxv=float(vals.max()) if len(vals) else 0
    for bar,value in zip(bars,vals):ax.text(value+(maxv*.025 if maxv else .02),bar.get_y()+bar.get_height()/2,f"{value:.3g} s",va="center",ha="left",fontsize=10,color="#1e293b",fontweight="bold")
    ax.set_xlim(0,max(0.1,maxv*1.25));ax.set_xlabel("Training Time (seconds)",color="#475569")
    ax.set_title("Training Time by Model",loc="left",fontsize=14,fontweight="bold",color="#172554",pad=12)
    ax.grid(axis="x",color="#e8edf5",linewidth=.8);ax.set_axisbelow(True);ax.spines[["top","right","left"]].set_visible(False);ax.spines["bottom"].set_color("#cbd5e1")
    ax.tick_params(axis="y",length=0,colors="#334155");fig.tight_layout();return fig


def build_interactive_metric_bar_html(metrics_df, columns, title):
    """Create actual DOM buttons for each saved bar; hover/touch effects do not rely on chart-library internals."""
    palette=["#7c3aed","#0284c7","#059669","#ea580c","#db2777","#ca8a04"]
    models=metrics_df.get("Model",pd.Series(dtype=str)).fillna("Unknown model").astype(str).tolist()
    present=[col for col in columns if col in metrics_df.columns]
    out=["<div class='interactive-bar-chart'>",f"<h3>{html_escape(title)}</h3>","<p class='bar-interaction-hint'>Hover, tap, or keyboard-focus any bar to highlight it and read its exact value.</p>","<div class='interactive-bar-legend'>"]
    for i,name in enumerate(models):
        out.append(f"<span class='bar-legend-item'><i style='--bar-color:{palette[i%len(palette)]}'></i>{html_escape(name)}</span>")
    out.append("</div><div class='interactive-bar-metrics'>")
    for column in present:
        metric_name=column.replace(" (%)","")
        values=_percentage_series(metrics_df,column).to_numpy(dtype=float)
        out.append(f"<section class='interactive-bar-metric'><h4>{html_escape(metric_name)}</h4>")
        for i,(name,value) in enumerate(zip(models,values)):
            if not np.isfinite(value):
                out.append(f"<div class='interactive-bar-row'><span class='interactive-bar-name'>{html_escape(name)}</span><span class='bar-not-available'>Not available</span></div>")
                continue
            shown=float(value);width=max(0.0,min(100.0,shown));color=palette[i%len(palette)]
            exact=f"{shown:.2f}%";aria=html_escape(f"{name}, {metric_name}: {exact}",quote=True)
            out.append(f"<div class='interactive-bar-row'><span class='interactive-bar-name'>{html_escape(name)}</span><button type='button' class='interactive-bar' aria-label='{aria}' title='{aria}' style='--bar-width:{width:.2f}%;--bar-color:{color}'><span class='interactive-bar-fill'></span><span class='interactive-bar-value'>{exact}</span></button></div>")
        out.append("</section>")
    out.append("</div></div>")
    return "".join(out)


def build_dashboard_training_pie(metrics_df):
    """Interactive training-time-share pie retained on the Dashboard."""
    palette=["#7c3aed","#0284c7","#059669","#ea580c","#db2777","#ca8a04"]
    names=metrics_df.get("Model",pd.Series(dtype=str)).fillna("Unknown model").astype(str).tolist()
    if "Training Time (sec)" not in metrics_df.columns:
        fig=go.Figure();fig.add_annotation(text="Training-time values are not available",x=.5,y=.5,showarrow=False)
        return _style_interactive_plot(fig,"Training Time Share",height=380)
    values=pd.to_numeric(metrics_df["Training Time (sec)"],errors="coerce").to_numpy(dtype=float)
    valid=np.isfinite(values)&(values>0)
    if not valid.any():
        fig=go.Figure();fig.add_annotation(text="Training-time values are not available",x=.5,y=.5,showarrow=False)
        return _style_interactive_plot(fig,"Training Time Share",height=380)
    pie_names=np.asarray(names)[valid].tolist();pie_values=values[valid].tolist()
    colors=[palette[i%len(palette)] for i,keep in enumerate(valid) if keep]
    fig=go.Figure(go.Pie(labels=pie_names,values=pie_values,marker={"colors":colors,"line":{"color":"#ffffff","width":2}},hole=.32,textinfo="label+percent",
        hovertemplate="<b>%{label}</b><br>Training time: %{value:.3g} seconds<br>Share: %{percent}<extra>Touch or hover for details</extra>"))
    return _style_interactive_plot(fig,"Training Time Share",height=420)


def build_explainer_workflow_chart():
    fig, ax = plt.subplots(figsize=(9, 3.4)); fig.patch.set_facecolor("#ffffff"); ax.set_facecolor("#ffffff")
    ax.set_xlim(0, 10); ax.set_ylim(0, 4); ax.axis("off")
    nodes=[(0.25,1.65,1.75,1.0,"TEXT INPUT\nText sample","#eaf2ff"),(2.7,1.65,1.9,1.0,"LOADED\nCLASSIFIER","#eef2ff"),(5.45,2.45,1.85,1.0,"LIME\nLocal words","#f0fdf4"),(5.45,.75,1.85,1.0,"SHAP\nFeature impact","#faf5ff"),(8.0,1.65,1.7,1.0,"SENTIMENT\nExplanation","#fff7ed")]
    for x,y,w,h,label,color in nodes:
        box=FancyBboxPatch((x,y),w,h,boxstyle="round,pad=0.08,rounding_size=.12",facecolor=color,edgecolor="#b7c9e6",linewidth=1.5)
        ax.add_patch(box);ax.text(x+w/2,y+h/2,label,ha="center",va="center",fontsize=11,color="#172554",fontweight="bold")
    arrows=[((2.0,2.15),(2.68,2.15)),((4.6,2.3),(5.38,2.9)),((4.6,2.0),(5.38,1.25)),((7.32,2.9),(8.0,2.25)),((7.32,1.25),(8.0,2.05))]
    for a,b in arrows: ax.annotate("",xy=b,xytext=a,arrowprops={"arrowstyle":"->","lw":1.8,"color":"#64748b"})
    ax.set_title("Explainability workflow · conceptual, not measured output",loc="left",fontsize=14,fontweight="bold",color="#172554",pad=10)
    fig.tight_layout();return fig


def build_spark_workflow_chart():
    fig, ax = plt.subplots(figsize=(10, 4.8)); fig.patch.set_facecolor("#ffffff"); ax.set_facecolor("#ffffff")
    ax.set_xlim(0, 10); ax.set_ylim(0, 5); ax.axis("off")
    def box(x,y,w,h,text,fc="#f1f6ff",ec="#b7c9e6",size=10):
        patch=FancyBboxPatch((x,y),w,h,boxstyle="round,pad=0.08,rounding_size=.12",facecolor=fc,edgecolor=ec,linewidth=1.5)
        ax.add_patch(patch);ax.text(x+w/2,y+h/2,text,ha="center",va="center",fontsize=size,color="#172554",fontweight="bold")
    box(.25,1.95,1.8,1.05,"TEXT DATA\nInput partitions",fc="#eff6ff")
    cluster=FancyBboxPatch((2.7,.8),4.35,3.6,boxstyle="round,pad=0.08,rounding_size=.16",facecolor="#fffaf2",edgecolor="#fdba74",linewidth=1.8)
    ax.add_patch(cluster)
    ax.text(4.875,3.95,"APACHE SPARK CLUSTER",ha="center",va="center",fontsize=13,color="#9a3412",fontweight="bold")
    box(3.15,2.85,3.45,.55,"WORKER 1  ·  Prepare records",fc="#eff6ff",size=9)
    box(3.15,2.0,3.45,.55,"WORKER 2  ·  Transform features",fc="#f0fdf4",size=9)
    box(3.15,1.15,3.45,.55,"WORKER 3  ·  Aggregate results",fc="#faf5ff",size=9)
    box(7.7,1.95,2.0,1.05,"SUMMARIZED\nOUTPUT",fc="#f0fdf4",ec="#86efac")
    ax.annotate("",xy=(2.62,2.48),xytext=(2.1,2.48),arrowprops={"arrowstyle":"->","lw":2,"color":"#64748b"})
    ax.annotate("",xy=(7.62,2.48),xytext=(7.1,2.48),arrowprops={"arrowstyle":"->","lw":2,"color":"#64748b"})
    ax.set_title("Spark data flow · input → distributed workers → summary (conceptual)",loc="left",fontsize=13,fontweight="bold",color="#172554",pad=12)
    fig.tight_layout();return fig


def build_roc_context_chart():
    fig,ax=plt.subplots(figsize=(7.6,5.0));fig.patch.set_facecolor("#ffffff");ax.set_facecolor("#ffffff")
    ax.plot([0,1],[0,1],linestyle="--",color="#94a3b8",linewidth=2,label="Chance baseline (reference)")
    ax.scatter([0,1],[0,1],s=40,color="#94a3b8",zorder=3)
    ax.text(.5,.34,"Aggregate accuracy / F1 values are not enough\nto reconstruct a measured ROC curve.\nA real curve requires per-example labels and scores.",ha="center",va="center",fontsize=11,color="#334155",bbox={"boxstyle":"round,pad=.6","facecolor":"#f1f6ff","edgecolor":"#cbdcf5"})
    ax.set(xlim=(0,1),ylim=(0,1),xlabel="False Positive Rate",ylabel="True Positive Rate")
    ax.set_title("ROC context · reference only, not a model result",loc="left",fontsize=14,fontweight="bold",color="#172554",pad=12)
    ax.grid(color="#e8edf5",linewidth=.8);ax.legend(loc="upper left",frameon=False,fontsize=10)
    ax.spines[["top","right"]].set_visible(False);ax.spines[["left","bottom"]].set_color("#cbd5e1")
    fig.tight_layout();return fig


explainability_concept_chart=build_explainer_workflow_chart()
spark_concept_chart=build_spark_workflow_chart()
roc_context_chart=build_roc_context_chart()


